var GAME_TILE = 32;
var GAME_TILE_h = GAME_TILE / 2;

var Actor = function() {
    var self = {
        id: "",
        w: 16,
        h: 16,
        hw: 8,
        hh: 8,
        x: GAME_TILE * chunkCols * 3,
        y: GAME_TILE * chunkRows * 3,

        cx: 0,
        cy: 0,

        vx: 0,
        vy: 0,
        minVy: 0,
        maxVy: 0,

        xRemainder: 0,
        yRemainder: 0
    };

    self.moveX = function(amount, action) {
        self.xRemainder += amount;
        var move = Math.floor(self.xRemainder);

        if (move != 0) {
            self.xRemainder -= move;
            var sign = Math.sign(move);

            while (move != 0) {
                var hit = self.tileCollisionAt(self.x + sign, self.y, 0);
                if (hit == 0) {
                    // No solid in direction of movement
                    self.x += sign;
                    move -= sign;

                    self.moved = true;
                } else {
                    // Hit a solid
                    if (action != null) action(hit);
                    break;
                }
            }
        }
    };

    self.moveY = function(amount, action) {
        self.yRemainder += amount;
        var move = Math.floor(self.yRemainder);

        if (move != 0) {
            self.yRemainder -= move;
            var sign = Math.sign(move);

            while (move != 0) {
                var hit = self.tileCollisionAt(self.x, self.y + sign, 1);
                if (hit == 0) {
                    // No solid in direction of movement
                    self.y += sign;
                    move -= sign;

                    self.moved = true;
                } else {
                    // Hit a solid
                    if (action != null) action(hit);
                    break;
                }
            }
        }
    };
}

