function drawGame() {
    //console.log('drawGame');
    //requestAnimationFrame(drawGame);

    if (initiated && client != null) {
        //console.log('drawing');

        // //
        // Background rendering
        //
        tctx.clearRect(0, 0, gameCanvas.width, gameCanvas.height);
        log('clear game canvas width',gameCanvas.width,'height',gameCanvas.height)

        //tctx.fillStyle = 'cyan';
        //tctx.fillRect(0, 0, tileCache.width, tileCache.height);

        var xPlayer = chunkColPixels + (client.x + client.w);
        var yPlayer = chunkRowPixels + (client.y + client.h);
        var tx = -xPlayer + relX * TILE + (gameCanvas.width / 2);
        var ty = -yPlayer + relY * TILE + (gameCanvas.height / 2);

        // ~~ same as Math.floor(), for positive values
        var sourceX = ~~(xPlayer - relX * TILE - (gameCanvas.width / 2));
        var sourceY = ~~(yPlayer - relY * TILE - (gameCanvas.height / 2));

        //var sourceX = ~~(xPlayer - gameCanvas.width / 2);
        //var sourceY = ~~(yPlayer - gameCanvas.height / 2);

        //var sourceX = (-xPlayer + relX*TILE + gameCanvas.width / 2);
        //var sourceY = (-yPlayer + relY*TILE + gameCanvas.height / 2);

        // Draw entire cache
        //tctx.drawImage(tileCache, Math.floor(tx), Math.floor(ty));

        // Draw only visible part of cache
        tctx.drawImage(tileCache,
            // source rectangle
            sourceX, sourceY,
            gameCanvas.width * 2, gameCanvas.height * 2,

            // destination
            0, 0,
            gameCanvas.width * 2, gameCanvas.height * 2
        );


        // //
        // Foreground rendering
        //
        if (foregroundUpdated) {
            if (initiated) foregroundUpdated = false;
            ctx.clearRect(0, 0, tileCanvas.width, tileCanvas.height);

            // Set ctx values
            ctx.font = "16px Arial";

            // Players
            for (var i in Player.list) {
                Player.list[i].draw();
            }

            // Food
            for (var i in Food.list) {
                Food.list[i].draw();
            }

            // Dots
            for (var i in Dot.list) {
                Dot.list[i].draw();
            }
        }
    }

    requestAnimationFrame(drawGame);
}

