function setCookie(cname, cvalue, exdays) {
    var d = new Date();
    d.setTime(d.getTime() + (exdays * 24 * 60 * 60 * 1000));
    var expires = "expires=" + d.toUTCString();
    document.cookie = cname + "=" + cvalue + "; " + expires;
}
function getCookie(cname) {
    var name = cname + "=";
    var ca = document.cookie.split(';');
    for (var i = 0; i < ca.length; i++) {
        var c = ca[i];
        while (c.charAt(0) == ' ') {
            c = c.substring(1);
        }
        if (c.indexOf(name) == 0) {
            return c.substring(name.length, c.length);
        }
    }
    return "";
}
function calculateTileIndex(value, y, x, cy, cx) { // OPTIMIZE
    //var above, left, below, right;

    /*
    if (MAP[y - 1] != null) above = MAP[y - 1][x];
    if (MAP[y][x - 1] != null) left = MAP[y][x - 1];
    if (MAP[y][x + 1] != null) right = MAP[y][x + 1];
    if (MAP[y + 1] != null) below = MAP[y + 1][x];
    */

    //var above = MAP[relY * worldCols + (y - 1) * chunkCols + x];
    //var left = MAP[relY * worldCols + y * chunkCols + (x - 1)];
    //var right = MAP[relY * worldCols + y * chunkCols + (x + 1)];
    //var below = MAP[relY * worldCols + (y + 1) * chunkCols + x];
    //console.log('calcTileIndex ' + value + ', ' + y + ', ' + x + ', ' + cy + ', ' + cx);
    var calculated = ((cy + y) * worldCols + cx + x);
    //console.log('calculated: ' + calculated);

    /*if (calculated == 7825) {
        console.log(MAP + '');
    }*/

    var above = MAP[(cy + y - 1) * worldCols + cx + x];
    var left = MAP[(cy + y) * worldCols + cx + x - 1];
    var right = MAP[(cy + y) * worldCols + cx + x + 1];
    var below = MAP[(cy + y + 1) * worldCols + cx + x];

    //MAP[(yCoord * chunkRows + yc) * worldCols + xCoord * chunkCols + xc] = value;
    //var above = MAP[(cy * chunkRows + y - 1) * worldCols + cx * chunkCols + x] = value;
    //var left = MAP[(cy * chunkRows + y) * worldCols + cx * chunkCols + x - 1] = value;
    //var right = MAP[(cy * chunkRows + y) * worldCols + cx * chunkCols + x + 1] = value;
    //var below = MAP[(cy * chunkRows + y + 1) * worldCols + cx * chunkCols + x] = value;

    //Slow & steady
    var sum = 0;
    if (above == value) sum += 1;
    if (left == value) sum += 2;
    if (right == value) sum += 4;
    if (below == value) sum += 8;

    return sum;
}
