const keyHandler = function(e) {
    if (!initiated)
      return
    if (client == null || client.key == null)
      return

    // capture
    e.preventDefault()

    // fullscreen toggle
    if (e.keyCode == 70 && e.type == 'keydown') {
      if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen();
      } else if (document.exitFullscreen) {
        document.exitFullscreen();
      }
    }

    // add bot
    if (e.keyCode == 66 && e.type == 'keydown') {
      sendInput(98)
      return
    }

    e = e || window.event; //DEBUG DISABLE
    if (useWasd) {
        // a
        if (e.keyCode == 65) {
            client.key.left = (e.type == "keydown");
            sendInput(2, (client.key.left ? 1 : 0));
        }
        // d
        else if (e.keyCode == 68) {
            client.key.right = (e.type == "keydown");
            sendInput(3, (client.key.right ? 1 : 0));
        }
        // s
        else if (e.keyCode == 83) {
            client.key.down = (e.type == "keydown");
            sendInput(4, (client.key.down ? 1 : 0));
        }
        // w
        else if (e.keyCode == 87) {
            client.key.up = (e.type == "keydown");
            sendInput(5, (client.key.up ? 1 : 0));
        }
        // space
        if (e.keyCode == 32) {
            client.key.action = (e.type == "keydown");
            sendInput(6, (client.key.action ? 1 : 0));
        }
        if (e.keyCode == 16) {
            console.log('shift');
            client.key.blue = (e.type == "keydown");
            sendInput(7, (client.key.blue ? 1 : 0));
        }
    } else {
        // left
        if (e.keyCode == 37) {
            client.key.left = (e.type == "keydown");
            sendInput(2, (client.key.left ? 1 : 0));
        }
        // right
        else if (e.keyCode == 39) {
            client.key.right = (e.type == "keydown");
            sendInput(3, (client.key.right ? 1 : 0));
        }
        // down (fire)
        else if (e.keyCode == 83) {
            client.key.down = (e.type == "keydown");
            sendInput(4, (client.key.down ? 1 : 0));
        }
        // up
        else if (e.keyCode == 38) {
            client.key.up = (e.type == "keydown");
            sendInput(5, (client.key.up ? 1 : 0));
        }
        // space
        if (e.keyCode == 32) {
            client.key.action = (e.type == "keydown");
            sendInput(6, (client.key.action ? 1 : 0));
        }
        if (e.keyCode == 16) {
            console.log('shift');
            client.key.blue = (e.type == "keydown");
            sendInput(7, (client.key.blue ? 1 : 0));
        }
    }
}
