// std util
export const log = console.log
export const range = (len) => {
  const arr = []
  for (let i = 0; i < len; i++)
    arr.push(i)
  return arr
}
export const partition = (array, n) => {
  const res = []
  for (var i = 0; i < array.length; i += n) {
    res.push(array.slice(i, i+n))
  }
  return res
  // return array.length ? [array.splice(0, n)].concat(partition(array, n)) : []
}
export const shuffle = (array) => {
  let currentIndex = array.length;

  // While there remain elements to shuffle...
  while (currentIndex != 0) {

    // Pick a remaining element...
    let randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex--;

    // And swap it with the current element.
    [array[currentIndex], array[randomIndex]] = [
      array[randomIndex], array[currentIndex]];
  }
}
export const mapo = (obj, fn=()=>{}, path=[]) => {
  for (var property in obj) {
      if (obj.hasOwnProperty(property)) {
          if (typeof obj[property] == 'object') {
            const path1 = path.concat([property])
            fn(property, obj[property], path1)
            mapo(obj[property], fn, path1)
          }
      }
  }
}
export const access = (obj, path) => path.reduce((o,k) => {return o[k]}, obj)
export const formatResult = (str) => JSON.stringify(str, null, '  ')

// dom util
export const inViewport = (el, window, thresh=0) => {
  if (!el)
    return false
  const winheight = window.innerHeight
  const rect = el.getBoundingClientRect() 
  var amtVisible = rect.height
  if (rect.top < 0)
    amtVisible = rect.bottom
  else if (rect.bottom > winheight)
    amtVisible = winheight - rect.top
  const percVisible = amtVisible/rect.height
  return percVisible > thresh
}

// react utilities
export const useStore = (id, val0) => {
  const [val, setVal] = useState(() => {
    const storedRaw = localStorage.getItem(id)
    // log(`storedRaw ${id}: ${storedRaw}`)
    // log(storedRaw)
    const stored = storedRaw != null ? JSON.parse(storedRaw)
                                     : null
    // log(`stored ${id}: ${stored}`)
    // log(stored)
    const res = stored != null ? stored.value
                               : val0
    // log(`init ${id}: ${res}`)
    return res
  })
  useEffect(() => {
    // log(`store ${id}: ${val}`)
    // localStorage.setItem(id, val)
    localStorage.setItem(id, JSON.stringify({value: val}))
  }, [val])
  const resetVal = () => localStorage.removeItem(id)
  // return [val, setVal, resetVal]
  return {
    val,
    set: setVal,
    reset: resetVal
  }
}
export const makeState = (initVal) => {
  const [val, setVal] = useState(initVal)
  return {val: val, set: setVal}
}

// react comps
export const tooltip = ({id, title, content, style={}}) => {
  return <Tooltip
           key={id}
           title={title}
           placement='top'
           followCursor
           enterDelay={0}
           leaveDelay={0}
           enterNextDelay={0}
           TransitionComponent={Fade}
           TransitionProps={{timeout: 0}}
           style={style}>
           {content}
         </Tooltip>
}
export const toolButton = ({id, title, icon, click, invert=false, iconClass=''}) => {
  const buttonStyle = {
    backgroundColor: 'Transparent',
    backgroundRepeat: 'no-repeat',
    border: 'none',
    cursor: 'pointer',
    overflow: 'hidden',
    outline: 'none',
  }
  return tooltip({
           id: id,
           title: title,
           content: (
             <button onClick={click} style={buttonStyle}>
               <FontAwesomeIcon className={`icon ${iconClass}`} color={invert ? '#b1aeb1' : '#b1aeb1'} icon={icon}/>
             </button>
           ),
         })
}
export function useIsVisible(ref) {
  const [isIntersecting, setIntersecting] = useState(false)

  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) =>
      setIntersecting(entry.isIntersecting)
    )

    observer.observe(ref.current)
    return () => {
      observer.disconnect()
    }
  }, [ref])
  
  return isIntersecting
}
